    # Minimal in-memory stand-in for the Django ORM (Django is not installed here).
    class QuerySet(list):
        def filter(self, **kwargs):
            result = []
            for obj in self:
                ok = True
                for key, value in kwargs.items():
                    field, _, op = key.partition('__')
                    actual = getattr(obj, field)
                    if op == 'gt':
                        ok = ok and actual > value
                    elif op == 'gte':
                        ok = ok and actual >= value
                    elif op == 'lt':
                        ok = ok and actual < value
                    elif op == 'lte':
                        ok = ok and actual <= value
                    else:
                        ok = ok and actual == value
                if ok:
                    result.append(obj)
            return QuerySet(result)

        def __repr__(self):
            return '<QuerySet [%s]>' % ', '.join(repr(o) for o in self)

    class Manager:
        def __init__(self):
            self.rows = []

        def create(self, **kwargs):
            obj = self.model(**kwargs)
            self.rows.append(obj)
            return obj

        def all(self):
            return QuerySet(self.rows)

        def filter(self, **kwargs):
            return self.all().filter(**kwargs)

    class Model:
        def __init__(self, **kwargs):
            for k, v in kwargs.items():
                setattr(self, k, v)

        def __init_subclass__(cls, **kw):
            cls.objects = Manager()
            cls.objects.model = cls

        def __repr__(self):
            return '<%s: %s>' % (type(self).__name__, self)

    class Author(Model):
        def __str__(self):
            return self.name

    class Book(Model):
        def __str__(self):
            return self.title

        def __init__(self, **kwargs):
            if isinstance(kwargs.get('published_date'), str):
                kwargs['published_date'] = datetime.date.fromisoformat(kwargs['published_date'])
            super().__init__(**kwargs)

